+const ERP_TIMEOUT_MS_DEFECTO = 5000;
+
+// Configuración del conector ERP: ERP_TIMEOUT_MS (ms, entero positivo); 5000 si no está definida.
+export function configuracionErp(env = process.env) {
+  const crudo = env.ERP_TIMEOUT_MS;
+  if (crudo === undefined) return { timeoutMs: ERP_TIMEOUT_MS_DEFECTO };
+  if (!/^[0-9]+$/.test(String(crudo)) || Number(crudo) <= 0 || !Number.isSafeInteger(Number(crudo)))
+    throw new RangeError(`ERP_TIMEOUT_MS inválido: debe ser un entero positivo en milisegundos (recibido: ${JSON.stringify(crudo)})`);
+  return { timeoutMs: Number(crudo) };
+}
